"""Consensus of forward/backward observers on a finite chain."""
from __future__ import annotations
from itertools import combinations
from typing import FrozenSet, Iterable, List, Set

OpenSet = FrozenSet[int]
Topology = Set[OpenSet]

def generate_topology(carrier: FrozenSet[int], gens: Iterable[OpenSet]) -> Topology:
    base: Set[OpenSet] = {frozenset(), carrier} | {frozenset(g) & carrier for g in gens}
    changed = True
    while changed:
        changed = False
        for a, b in combinations(list(base), 2):
            if (a & b) not in base:
                base.add(a & b); changed = True
    opens: Set[OpenSet] = set(base)
    changed = True
    while changed:
        changed = False
        for a, b in combinations(list(opens), 2):
            if (a | b) not in opens:
                opens.add(a | b); changed = True
    return opens

def order_top(pts: List[int]) -> Topology:
    c = frozenset(pts); g: List[OpenSet] = []
    for i in pts:
        for j in pts:
            g.append(frozenset(p for p in pts if i < p < j))
        g.append(frozenset(p for p in pts if p < i))
        g.append(frozenset(p for p in pts if p > i))
    return generate_topology(c, g)

def forward(pts: List[int]) -> Topology:
    c = frozenset(pts); g: List[OpenSet] = []
    for i in pts:
        for j in pts:
            g.append(frozenset(p for p in pts if i <= p < j))
        g.append(frozenset(p for p in pts if p >= i))
    return generate_topology(c, g)

def backward(pts: List[int]) -> Topology:
    c = frozenset(pts); g: List[OpenSet] = []
    for i in pts:
        for j in pts:
            g.append(frozenset(p for p in pts if i < p <= j))
        g.append(frozenset(p for p in pts if p <= i))
    return generate_topology(c, g)

if __name__ == "__main__":
    pts = [0, 1, 2, 3]
    cons = forward(pts) & backward(pts)
    print("consensus == order topology:", cons == order_top(pts))

